import assert from "node:assert/strict";
import { z } from "zod";
const hash=z.string().regex(/^[a-f0-9]{64}$/),id=z.string().min(1).max(200),source=z.enum(["base","head"]);
const declaration=z.object({id,source,operation:id,endpoint:z.string().startsWith("/api/v1/"),repetition:z.number().int().min(1).max(3),fixture:id,warmup:z.boolean()}).strict();
const fixture=z.object({id,source,sha256:hash,schema:z.number().int().positive(),generation:z.uuid(),cursor:z.string().regex(/^\d+$/)}).strict();
const resources=z.record(id,z.array(id).min(1));
const prepared=z.object({version:z.literal(1),scope:z.literal("task1-qualification"),sources:z.object({base:hash,head:hash}).strict(),helperSHA256:hash,runtimeSHA256:hash,builds:z.object({base:hash,head:hash}).strict(),intendedIds:z.array(id).min(1),declarations:z.array(declaration).min(1),fixtures:z.array(fixture).min(1),requiredResources:resources,correctness:z.object({cli:z.object({originalSHA256:hash,exitCode:z.literal(0),declared:z.array(id).min(1),acks:z.array(id).min(1)}).strict(),tabs:z.array(z.object({id,originalSHA256:hash,generation:z.uuid()}).strict()).length(2)}).strict(),officialWorkloadComplete:z.boolean()}).strict();
export type PreparedCampaign=z.infer<typeof prepared>;
const resultSchema=z.object({samples:z.array(z.object({id,accepted:z.boolean(),failure:z.string().nullable()}).strict()),resources:z.record(id,z.record(id,z.number().finite().nonnegative())),shutdown:z.object({closed:z.boolean(),stdioClosed:z.boolean(),exitCode:z.number().int().nullable(),signalCode:z.string().nullable()}).strict()}).strict();
export type CampaignResult=z.infer<typeof resultSchema>;
function unique(values:string[],label:string){assert.equal(new Set(values).size,values.length,`duplicate ${label}`);}
export function validatePrepared(input:unknown){
 const value=prepared.parse(input);assert.equal(value.officialWorkloadComplete,false,"Task1 qualification cannot claim official protocol readiness");unique(value.intendedIds,"intended IDs");unique(value.declarations.map(r=>r.id),"sample IDs");assert.deepEqual(value.declarations.map(r=>r.id),value.intendedIds,"missing or wrong intended sample IDs");unique(value.fixtures.map(r=>r.id),"fixture IDs");
 for(const row of value.declarations)assert(value.fixtures.some(f=>f.id===row.fixture&&f.source===row.source),"unbound declaration fixture/source");
 assert(Object.keys(value.requiredResources).length>0,"required resource owners absent");
 for(const keys of Object.values(value.requiredResources))unique(keys,"resource keys");
 for(const owner of ["service","browser"])assert(Object.hasOwn(value.requiredResources,owner),"required resource owner absent "+owner);
 const cli=value.correctness.cli;unique(cli.declared,"CLI IDs");unique(cli.acks,"CLI ACKs");assert.deepEqual([...cli.acks].sort(),[...cli.declared].sort(),"actual CLI acknowledgement witness incomplete");
 unique(value.correctness.tabs.map(t=>t.id),"tab IDs");assert(value.correctness.tabs.every(t=>value.fixtures.some(f=>f.generation===t.generation)),"stale two-tab generation");
 return {value,intended:value.intendedIds.length,officialReady:false as const};
}
export function validateResult(input:PreparedCampaign,observation:unknown){
 const result=resultSchema.parse(observation),{value,intended}=validatePrepared(input),wanted=new Set(value.declarations.map(r=>r.id));const counts=new Map<string,number>();
 for(const row of result.samples)counts.set(row.id,(counts.get(row.id)??0)+1);
 const missing=[...wanted].filter(id=>!counts.has(id)),failed=result.samples.filter(r=>!wanted.has(r.id)||counts.get(r.id)!==1||!r.accepted||r.failure!==null).map(r=>r.id);
 const resourceValid=Object.entries(value.requiredResources).every(([owner,keys])=>keys.every(key=>Object.hasOwn(result.resources[owner]??{},key)&&result.resources[owner][key]===0));
 const s=result.shutdown,shutdownValid=s.closed&&s.stdioClosed&&s.exitCode===0&&s.signalCode===null;
 return {intended,attempted:result.samples.length,accepted:result.samples.filter(r=>wanted.has(r.id)&&r.accepted&&r.failure===null).length,rejected:result.samples.filter(r=>!r.accepted).length,missing,failed,acceptance:!missing.length&&!failed.length&&resourceValid&&shutdownValid};
}

import { isAbsolute } from "node:path";
import { readFileSync,lstatSync } from "node:fs";
import { sha256,fileSHA256,ownedDirectory,validateOutputRoot } from "./w04-qualification";
import { matchEndpoint,validResourceId } from "../../src/contracts/routes";
import { validateJourney } from "./w04-journey";
import { validateUpgrade } from "./w04-upgrade";
import { databasePins,validateClosedResources } from "./w04-resources";
import {canonicalDigest} from "../../src/domain/request-digest";
import { requiredResources } from "./w04-resources";
const proofReference=z.object({path:z.string().refine(isAbsolute),sha256:hash}).strict();
const finiteDeclaration=z.object({id,kind:z.enum(["request","loadEvent","loadVisibility","workflowVisibility","interaction","queuedEvent","flush","sseCycle"]),source,operation:id,endpoint:z.string().startsWith("/api/v1/"),method:z.enum(["GET","POST"]),repetition:z.number().int().min(1).max(3),fixture:id,warmup:z.boolean(),ordinal:z.number().int().nonnegative(),body:z.unknown().optional(),key:z.uuid(),role:z.enum(["reporter","operator"]),expectedStatus:z.union([z.literal(200),z.literal(201)]),tab:z.number().int().min(0).max(1).optional(),eventId:z.uuid().optional(),runId:z.uuid().optional(),nodeId:z.uuid().optional(),phase:z.enum(["sustained","burst"]).optional(),dueMs:z.number().nonnegative().optional()}).strict();
const stoppedFixture=z.object({id,source,dir:z.string().refine(isAbsolute),generation:z.uuid(),cursor:z.string().regex(/^\d+$/),schema:z.number().int().positive(),cohort:z.enum(["load","comparison","workflow","usage","flush","resources"]),facts:proofReference,originalPins:proofReference,audit:proofReference,setup:proofReference}).strict();
const finalPrepared=z.object({version:z.literal(2),scope:z.literal("w04-release"),sources:z.object({base:hash,head:hash}).strict(),helperSHA256:hash,runtimeSHA256:hash,builds:z.object({base:hash,head:hash}).strict(),binding:proofReference,templates:proofReference,capabilities:z.object({ffmpeg:proofReference}).strict(),intendedIds:z.array(id).min(1),declarations:z.array(finiteDeclaration).min(1),fixtures:z.array(stoppedFixture).min(1),requiredResources:resources,resourceOwners:z.object({service:z.array(id).min(1),browser:z.array(id).min(1)}).strict(),output:z.object({root:z.string().refine(isAbsolute),identity:z.object({path:z.string(),dev:z.number().int(),ino:z.number().int(),uid:z.number().int(),gid:z.number().int(),mode:z.literal(448)}).strict(),files:z.array(id).min(1)}).strict(),witnesses:z.object({cli:proofReference,tabs:proofReference,resources:proofReference,upgrade:proofReference,fullChecks:proofReference,appearance:proofReference}).strict(),rateLimits:z.object({setup:z.literal("12ms minimum pause; rejected setup fails preparation"),load:z.literal("all 7000 logical event IDs must be accepted on declared cadence; 429 is a failed official scenario"),separateControls:z.literal("preparation/control only; rejected attempts never enter accepted latency")}).strict(),operationTimingRows:z.array(z.never()).length(0),officialWorkloadComplete:z.literal(true)}).strict();
export type W04PreparedCampaign=z.infer<typeof finalPrepared>;
export type FiniteDeclaration=z.infer<typeof finiteDeclaration>;
function originalProof(reference:z.infer<typeof proofReference>){const stat=lstatSync(reference.path);assert(stat.isFile()&&!stat.isSymbolicLink()&&stat.uid===process.getuid!()&&(stat.mode&0o777)===0o600,"private original proof required");assert.equal(fileSHA256(reference.path),reference.sha256,"original proof hash changed");return JSON.parse(readFileSync(reference.path,"utf8"));}
export function validateW04Prepared(input:unknown){
 const value=finalPrepared.parse(input);unique(value.intendedIds,"intended IDs");unique(value.declarations.map(r=>r.id),"sample IDs");assert.deepEqual(value.declarations.map(r=>r.id),value.intendedIds,"finite intended sample mismatch");unique(value.fixtures.map(f=>f.id),"fixture IDs");
 const fixtures=new Map(value.fixtures.map(f=>[f.id,f]));
 for(const row of value.declarations){assert(fixtures.get(row.fixture)?.source===row.source,"finite source/fixture mismatch");assert(!/[{}]/.test(row.endpoint),"unresolved endpoint placeholder");assert.equal(row.warmup,row.kind==="request"&&row.ordinal<10,"warmup mismatch");const matched=matchEndpoint(row.method,new URL(row.endpoint,"http://127.0.0.1").pathname);assert(matched&&validResourceId(matched.id),"unknown or invalid public endpoint");if(["request","loadEvent","queuedEvent"].includes(row.kind)&&row.method==="POST"){assert(row.body!==undefined,"command body missing");matched.endpoint.input.parse(row.body);assert.equal(row.expectedStatus,matched.endpoint.status,"command expected status mismatch");assert.equal(row.role,matched.endpoint.access==="human"?"operator":"reporter","command role mismatch");}if(row.method==="GET"){matched.endpoint.input.parse(Object.fromEntries(new URL(row.endpoint,"http://127.0.0.1").searchParams));assert.equal(row.expectedStatus,matched.endpoint.status);assert.equal(row.role,matched.endpoint.access==="human"?"operator":"reporter");}if(row.kind.endsWith("Visibility")){assert.equal(row.source,"head");assert(row.eventId&&row.runId&&row.tab!==undefined,"visible event/run/tab missing");}if(row.kind==="loadEvent")assert(row.eventId&&row.runId&&row.phase&&row.dueMs!==undefined,"load cadence identity missing");}
 for(const f of value.fixtures)ownedDirectory(f.dir,true);assert.deepEqual(validateOutputRoot(value.output.root),value.output.identity,"official output identity changed");const capability=originalProof(value.capabilities.ffmpeg);assert(capability.executable&&capability.versionExit===0&&capability.licenseExit===0&&capability.sha256===fileSHA256(capability.executable),"video capability changed");
 unique(value.resourceOwners.service,"service owner IDs");unique(value.resourceOwners.browser,"browser owner IDs");for(const f of value.fixtures)assert(value.resourceOwners.service.includes(f.id),"unbound service resource owner");unique(value.output.files,"output names");assert.equal(value.output.root,value.output.identity.path);assert(value.fixtures.every(f=>f.dir.startsWith(value.output.root.slice(0,value.output.root.lastIndexOf("/"))+"/")),"fixture outside prepared owner");
 assert.deepEqual(value.requiredResources,Object.fromEntries(Object.entries(requiredResources).map(([owner,keys])=>[owner,[...keys]])),"required observable owner inventory mismatch");
 for(const fixture of value.fixtures){const audit=originalProof(fixture.audit),pins=originalProof(fixture.originalPins);originalProof(fixture.setup);assert.equal(audit.integrity,"ok");assert.deepEqual(audit.foreignKeys,[]);assert(audit.rows&&audit.schema&&typeof audit.rows==="object"&&!Array.isArray(audit.rows),"incomplete stopped SQL");assert.deepEqual(Object.keys(audit.rows).sort(),audit.schema.filter((r:{type:string})=>r.type==="table").map((r:{name:string})=>r.name).sort(),"SQL table coverage incomplete");for(const name of ["instance_metadata","migration_history","receipts","changes","runs","run_events","tasks","projects"])assert(Array.isArray(audit.rows[name]),"required SQL rows absent");const facts=originalProof(fixture.facts);if(fixture.cohort==="workflow"){assert.equal(audit.rows.workflows.length,100);assert.equal(audit.rows.workflow_revisions.length,100);assert.equal(audit.rows.workflow_revisions.reduce((n:number,r:{nodes:string})=>n+JSON.parse(r.nodes).length,0),10000);assert.equal(audit.rows.workflow_revisions.reduce((n:number,r:{edges:string})=>n+JSON.parse(r.edges).length,0),20000);}else{assert.equal(audit.rows.tasks.length,1000);assert.equal(facts.facts.tasks.length,1000);assert.equal(facts.facts.runs.length,10);assert.equal(audit.rows.run_events.length,fixture.cohort==="usage"?10010:10000);}assert.deepEqual(audit.before,audit.after);assert.deepEqual(audit.after,pins);assert.deepEqual(databasePins(fixture.dir),pins,"frozen original fixture changed");assert.equal(audit.rows.instance_metadata[0].generation,fixture.generation);assert.equal(audit.rows.instance_metadata[0].schema_version,fixture.schema);const cursor=Math.max(0,...audit.rows.changes.map((r:{id:number})=>r.id));assert.equal(String(cursor),fixture.cursor,"stale fixture cursor");}
 const templates=originalProof(value.templates);for(const f of value.fixtures){const template=templates[f.id];assert(template&&template.destination===value.output.root+"/"+f.id&&Number.isInteger(template.port)&&template.port>=1024&&template.port<=65535,"template route/port mismatch");assert.deepEqual(template.facts,originalProof(f.facts),"template facts changed");const rows=value.declarations.filter(r=>r.fixture===f.id);if(f.cohort==="load"){assert.deepEqual(rows.filter(r=>r.kind==="loadEvent").map(r=>({body:r.body,phase:r.phase,dueMs:r.dueMs})),template.facts.events.map((e:{body:unknown;phase:string;dueMs:number})=>({body:e.body,phase:e.phase,dueMs:e.dueMs})),"load declaration/template mismatch");}if(f.cohort==="workflow"){for(const row of rows.filter(r=>r.kind==="workflowVisibility")){assert.deepEqual(row.body,template.facts.markers[row.ordinal],"workflow marker/template mismatch");const body=row.body as {eventId:string;workflowRunId:string;payload:{nodeId:string}};assert.equal(body.eventId,row.eventId);assert.equal(body.workflowRunId,row.runId);assert.equal(body.payload.nodeId,row.nodeId);}}if(f.cohort==="flush"){for(const row of rows.filter(r=>r.kind==="queuedEvent")){const queue=template.facts.queued.find((q:{body:{eventId:string}})=>q.body.eventId===row.eventId);assert(queue,"queued template absent");assert.deepEqual(row.body,queue.body);const bytes=Buffer.from(queue.originalBytesBase64,"base64");assert.equal(bytes.length,queue.bytes);assert.equal(sha256(bytes),queue.fileSha256);assert.equal(canonicalDigest(queue.body),queue.digest);assert.deepEqual(JSON.parse(bytes.toString()).body,row.body);}}}
 const binding=originalProof(value.binding);assert.equal(binding.head.fingerprint,value.sources.head);assert.equal(binding.base.fingerprint,value.sources.base);
 validateWitnesses(value.witnesses,value.capabilities.ffmpeg,binding.head.fingerprint);
 const grouped=(kind:FiniteDeclaration["kind"],operation?:string,repetition?:number,sourceName?:"base"|"head")=>value.declarations.filter(r=>r.kind===kind&&(operation===undefined||r.operation===operation)&&(repetition===undefined||r.repetition===repetition)&&(sourceName===undefined||r.source===sourceName));
 const operations=["ingestion","tasks","detail","board","overview","tracking","events","activity","runs","run","tracking.run","registration","close","tracking.tasks","tracking.board"];
 for(let repetition=1;repetition<=3;repetition++){
  for(const operation of operations){const baseRows=grouped("request",operation,repetition,"base"),headRows=grouped("request",operation,repetition,"head");assert.deepEqual(baseRows.map(({endpoint,method,body,key,ordinal})=>({endpoint,method,body,key,ordinal})),headRows.map(({endpoint,method,body,key,ordinal})=>({endpoint,method,body,key,ordinal})),"paired request bytes differ");}
  for(const operation of operations)for(const sourceName of ["base","head"] as const){const rows=grouped("request",operation,repetition,sourceName);assert.equal(rows.length,110,"paired finite cohort incomplete "+operation);assert.deepEqual(rows.map(r=>r.ordinal),Array.from({length:110},(_,i)=>i));}
  for(const operation of ["workflow.list","workflow.metadata","workflow.revision","workflow.runSnapshot","usage.snapshot","usage.unique","usage.logicalDuplicate"]){assert.equal(grouped("request",operation,repetition,"head").length,110,"head finite cohort incomplete "+operation);assert.equal(grouped("request",operation,repetition,"base").length,0,"baseline lacks head-only feature");}
  for(const operation of ["export.v2","price.create"])assert.equal(grouped("request",operation,repetition,"head").length,20,"head transfer cohort incomplete");
  const load=grouped("loadEvent",undefined,repetition);assert.equal(load.length,7000);assert.equal(load.filter(r=>r.phase==="sustained").length,6000);assert.equal(load.filter(r=>r.phase==="burst").length,1000);unique(load.map(r=>r.eventId!),"load event IDs");assert.equal(new Set(load.map(r=>r.runId)).size,10);
  for(const phase of ["sustained","burst"] as const)for(const tab of [0,1]){const visible=grouped("loadVisibility",undefined,repetition).filter(r=>r.phase===phase&&r.tab===tab);assert.equal(visible.length,phase==="sustained"?60:4);for(const row of visible)assert(load.some(e=>e.eventId===row.eventId&&e.runId===row.runId&&e.phase===row.phase),"visibility not joined to exact load event");}
  for(const tab of [0,1]){assert.equal(grouped("workflowVisibility",undefined,repetition).filter(r=>r.tab===tab).length,10);assert.equal(grouped("interaction",undefined,repetition).filter(r=>r.tab===tab).length,10);}
  assert.equal(grouped("queuedEvent",undefined,repetition).length,1000);assert.equal(grouped("flush",undefined,repetition).length,1);
 }
 assert.equal(grouped("sseCycle").length,100);assert.equal(value.declarations.length,36937,"finite denominator changed");return {value,intended:value.intendedIds.length,officialReady:true as const};
}

export function validateWitnesses(input:unknown,ffmpeg:unknown,headFingerprint?:string){
 const witnesses=finalPrepared.shape.witnesses.parse(input),capability=originalProof(proofReference.parse(ffmpeg));assert(capability.executable&&capability.versionExit===0&&capability.licenseExit===0&&capability.sha256===fileSHA256(capability.executable),"video capability changed");
 if(headFingerprint){for(const ref of Object.values(witnesses)){const original=originalProof(ref);assert(original.bindings?.before&&original.bindings?.after,"current witness source binding absent");const before=originalProof(proofReference.parse(original.bindings.before)),after=originalProof(proofReference.parse(original.bindings.after));assert.equal(before.fingerprint,headFingerprint,"stale witness source");assert.deepEqual(before,after,"witness source changed during execution");}}
 const cli=originalProof(witnesses.cli),tabs=originalProof(witnesses.tabs);validateJourney(cli.witness);validateJourney(tabs.witness);assert(cli.commands?.length&&cli.cliWires?.length&&tabs.tabWitnesses?.length===2,"actual CLI/two-tab originals absent");assert(cli.witness.cli.every((c:{exitCode:unknown;closed:unknown})=>c.exitCode===0&&c.closed===true),"CLI boolean or status invalid");assert(tabs.tabWitnesses.every((t:{independentlyPaired:unknown;snapshot:{headerGeneration:string;body:{generation:string}}})=>t.independentlyPaired===true&&t.snapshot.headerGeneration===t.snapshot.body.generation),"current paired generation mismatch");
 const resource=originalProof(witnesses.resources);validateClosedResources(resource.resources);assert(resource.services?.length&&resource.services.every((s:{closed:unknown;exitCode:unknown;signalCode:unknown})=>s.closed===true&&s.exitCode===0&&s.signalCode===null),"actual resource child shutdown absent");assert(resource.browserFacts?.some((r:{processAbsent:unknown})=>r.processAbsent===true),"actual owned browser shutdown absent");
 const upgrade=originalProof(witnesses.upgrade);validateUpgrade(upgrade.witness);assert(upgrade.commands?.length&&upgrade.final?.rows&&upgrade.services?.length,"actual upgrade originals absent");
 const checks=originalProof(witnesses.fullChecks);assert.deepEqual(checks.commands.map((c:{name:string})=>c.name),["test:unit","test:integration","test:e2e","lint","typecheck","openapi:check"]);assert(checks.commands.every((c:{exitCode:unknown;originals:z.infer<typeof proofReference>})=>c.exitCode===0&&originalProof(c.originals).exit===0),"complete original command pass required");
 const appearance=originalProof(witnesses.appearance);assert(appearance.captures?.length>=6&&appearance.recording?.enabled===true&&appearance.recording.path,"actual captures and recording absent");assert(appearance.captures.every((c:{facts:{overflow:unknown};violations:unknown[]})=>c.facts.overflow===false&&Array.isArray(c.violations)&&c.violations.length===0),"appearance correctness missing");
 return witnesses;
}

export function reconcileFinite(declarations:FiniteDeclaration[],samples:(FiniteDeclaration&{accepted:boolean;failure:string|null;ms?:number})[]){
 unique(declarations.map(r=>r.id),"frozen finite IDs");unique(samples.map(r=>r.id),"observed finite IDs");const intended=new Map(declarations.map(r=>[r.id,r]));
 for(const row of samples){const expected=intended.get(row.id);assert(expected,"undeclared finite sample");for(const key of ["kind","source","fixture","operation","endpoint","method","repetition","warmup","ordinal"] as const)assert.deepEqual(row[key],expected[key],"observed declaration mismatch "+key);if(row.ms!==undefined)assert(Number.isFinite(row.ms)&&row.ms>=0,"invalid elapsed sample");}
 const missing=declarations.filter(r=>!samples.some(s=>s.id===r.id)).map(r=>r.id),failed=samples.filter(r=>!r.accepted||r.failure!==null).map(r=>r.id);return {intended:declarations.length,attempted:samples.length,accepted:samples.filter(r=>r.accepted&&r.failure===null).length,rejected:samples.filter(r=>!r.accepted).length,missing,failed,complete:!missing.length&&!failed.length};
}
